func (u *webUseCases) Sprint(ctx context.Context, project, slug string) (WebSprintResult, error) {
	items, err := u.dashboard.SprintSummaries(ctx)
	if err != nil {
		return WebSprintResult{}, err
	}
	for _, item := range items {
		if item.Project == project && item.Slug == slug {
			result := u.webSprint(item)
			result.AttentionFindings = append([]DisplayFinding(nil), result.Findings...)
			if len(result.AttentionFindings) > 3 {
				result.AttentionFindings = result.AttentionFindings[:3]
			}
			result.Overview = u.sprintOverview(project, slug)
			result.RunStages = sprintRunStages(item)
			u.annotateStageModels(&result)
			result.TotalStages = len(result.RunStages)
			for _, stage := range result.RunStages {
				if stage.Status == "complete" || stage.Status == "completed" || stage.Status == "skipped" {
					result.CompletedStages++
					continue
				}
				if result.CurrentStage == "" {
					result.CurrentStage = stage.Name
				}
			}
			u.enrichSprintDashboard(&result)
			return result, nil
		}
	}
	return WebSprintResult{}, ErrWebNotFound
}

func (u *webUseCases) PromptBundle(ctx context.Context, project, slug, stageName string) (WebPromptBundleResult, error) {
	if err := ctx.Err(); err != nil {
		return WebPromptBundleResult{}, err
	}
	stage := sprint.PlanningStage(stageName)
	result := WebPromptBundleResult{
		Stage:         stage,
		Scope:         "Deterministic stage preview",
		InputContract: sprint.InputContract(stage),
	}
	service := u.dashboard.sprintService()
	var (
		preview sprint.PromptPreview
		err     error
	)
	switch stage {
	case sprint.StageRequirements:
		preview, err = service.PromptRequirements(project, slug)
	case sprint.StageCodeContext:
		preview, err = service.PromptCodeContext(project, slug)
	case sprint.StageSprintIndex:
		preview, err = service.PromptSprintIndex(project, slug)
	case sprint.StageTechnicalHandbook:
		preview, err = service.PromptTechnicalHandbook(project, slug)
	case sprint.StageAreaReasoning:
		result.Scope = "First selected area prompt"
		preview, err = service.PromptAreaReasoning(project, slug)
	case sprint.StageReasoning:
		preview, err = service.PromptReasoning(project, slug)
	case sprint.StagePlan:
		preview, err = service.PromptPlan(project, slug)
	case sprint.StageExecute:
		result.Scope = "One session for the ordered task queue"
		preview, err = service.PromptExecute(project, slug, sprint.ExecuteRequest{})
	case sprint.StageReview:
		result.Scope = "Conformance Review manifest preview; worker suffixes vary"
		preview, err = service.PromptReview(project, slug, sprint.ReviewRequest{})
	case sprint.StageSmoke:
		result.Scope = "Prepared after smoke harness discovery"
		result.UnavailableReason = "The smoke prompt is assembled only after the governed harness and acceptance coverage are discovered."
		return result, nil
	default:
		return WebPromptBundleResult{}, ErrWebNotFound
	}
	if err := ctx.Err(); err != nil {
		return WebPromptBundleResult{}, err
	}
	if err != nil {
		result.UnavailableReason = displaySafe(err.Error())
		return result, nil
	}
	explanation := preview.Explanation
	if explanation == nil {
		value := sprint.ExplainPrompt(preview.Prompt)
		explanation = &value
	}
	contract := result.InputContract
	explanation.InputContract = &contract
	result.Available = true
	result.Explanation = explanation
	result.BlockContents = make([]string, 0, len(explanation.Blocks))
	offset := 0
	for _, block := range explanation.Blocks {
		end := offset + block.Bytes
		if end > len(preview.Prompt) {
			result.BlockContents = nil
			break
		}
		result.BlockContents = append(result.BlockContents, preview.Prompt[offset:end])
		offset = end
	}
	return result, nil
}

func (u *webUseCases) sprintOverview(project, slug string) string {
	path := filepath.Join(u.root, "projects", project, "sprints", slug, "requirements.md")
	data, err := os.ReadFile(path)
	if err != nil {
		return ""
	}
	lines := strings.Split(string(data), "\n")
	inGoal := false
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "## ") {
			if inGoal {
				break
			}
			inGoal = strings.EqualFold(strings.TrimSpace(strings.TrimPrefix(trimmed, "## ")), "Sprint Goal")
			continue
		}
		if inGoal && trimmed != "" {
			return strings.Trim(strings.TrimSpace(trimmed), "`*")
		}
	}
	return ""
}

// dashboardMarkdown is a deliberately small reader for governed Markdown. It
// extracts useful previews while leaving the source documents authoritative.
type dashboardMarkdown struct {
	sections map[string][]string
	order    []string
}

func readDashboardMarkdown(path string) dashboardMarkdown {
	result := dashboardMarkdown{sections: map[string][]string{}}
	file, err := os.Open(path)
	if err != nil {
		return result
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, 64<<10))
	if err != nil {
		return result
	}
	section := ""
	for _, raw := range strings.Split(string(data), "\n") {
		line := strings.TrimSpace(raw)
		if strings.HasPrefix(line, "## ") {
			section = strings.ToLower(strings.TrimSpace(strings.TrimPrefix(line, "## ")))
			result.order = append(result.order, section)
			continue
		}
		if section != "" && line != "" && !strings.HasPrefix(line, "<!--") {
			result.sections[section] = append(result.sections[section], line)
		}
	}
	return result
}

func (m dashboardMarkdown) first(names ...string) string {
	for _, name := range names {
		for _, heading := range m.order {
			lines := m.sections[heading]
			if strings.EqualFold(heading, name) || strings.Contains(heading, strings.ToLower(name)) {
				for _, line := range lines {
					clean := cleanDashboardLine(line)
					if clean != "" {
						return clean
					}
				}
			}
		}
	}
	return ""
}

func (m dashboardMarkdown) items(names ...string) []string {
	var out []string
	for _, name := range names {
		for _, heading := range m.order {
			lines := m.sections[heading]
			if !strings.EqualFold(heading, name) && !strings.Contains(heading, strings.ToLower(name)) {
				continue
			}
			for _, line := range lines {
				if strings.HasPrefix(line, "- ") || strings.HasPrefix(line, "* ") || strings.HasPrefix(line, "1. ") {
					if value := cleanDashboardLine(line); value != "" {
						out = append(out, value)
					}
				}
			}
		}
	}
	return out
}

func cleanDashboardLine(line string) string {
	line = strings.TrimSpace(line)
	line = strings.TrimPrefix(strings.TrimPrefix(strings.TrimPrefix(line, "- "), "* "), "1. ")
	line = strings.Trim(line, "`*# ")
	if strings.HasPrefix(line, "[") && strings.Contains(line, "]:") {
		line = strings.TrimSpace(strings.SplitN(line, "]:", 2)[1])
	}
	return line
}

func countDashboardItems(m dashboardMarkdown, names ...string) int {
	return len(m.items(names...))
}

func (u *webUseCases) enrichProjectDashboard(result *WebProjectResult) {
	base := filepath.Join(u.root, "projects", result.Name)
	index := readDashboardMarkdown(filepath.Join(base, "project-index.md"))
	result.Brief = WebProjectBrief{
		Goal:       index.first("project summary", "primary goal", "goal"),
		Phase:      index.first("current phase", "product phase", "phase"),
		Repository: index.first("target repository", "repository"),
		Validation: index.first("validation", "last validation"),
		NonGoals:   index.items("non-goals", "non goals"),
	}
	if result.Brief.Goal == "" {
		result.Brief.Goal = "Project goal has not been recorded in project-index.md."
	}
	for _, phase := range result.Roadmap {
		for _, item := range phase.Sprints {
			switch item.Status {
			case "delivered":
				result.Delivered++
			case "active":
				result.Active++
			default:
				result.Planned++
			}
		}
	}
	for _, sprint := range result.Sprints {
		if len(sprint.Findings) > 0 || sprint.Review.Stale || sprint.Smoke.Stale || sprint.Review.Failed > 0 || sprint.Execute.Failed > 0 {
			result.NeedsAttention++
		}
	}
	wanted := []struct{ file, kind string }{{"PRD.md", "Product"}, {"TRD.md", "Technical"}, {"ARCHITECTURE.md", "Architecture"}}
	for _, doc := range wanted {
		path := filepath.Join(base, doc.file)
		ref := ""
		for _, artifact := range result.Artifacts {
			if strings.EqualFold(filepath.Base(artifact.DisplayPath), doc.file) {
				path = filepath.Join(u.root, filepath.FromSlash(artifact.DisplayPath))
				ref = artifact.Ref
				break
			}
		}
		parsed := readDashboardMarkdown(path)
		if len(parsed.order) == 0 {
			continue
		}
		preview := WebDocumentPreview{Kind: doc.kind, Name: doc.file, Sections: len(parsed.order), Summary: parsed.first("goal", "summary", "overview", "purpose")}
		if preview.Summary == "" {
			preview.Summary = parsed.first(parsed.order[0])
		}
		if info, err := os.Stat(path); err == nil {
			preview.Modified = info.ModTime().Format("2 Jan 2006")
		}
		preview.Ref = ref
		result.Documents = append(result.Documents, preview)
	}
}

func (u *webUseCases) enrichSprintDashboard(result *WebSprintResult) {
	base := filepath.Join(u.root, "projects", result.Project, "sprints", result.Slug)
	requirements := readDashboardMarkdown(filepath.Join(base, "requirements.md"))
	index := readDashboardMarkdown(filepath.Join(base, "sprint-index.md"))
	result.Mission = WebSprintMission{
		Goal:               requirements.first("sprint goal", "goal"),
		Output:             requirements.first("planned output", "deliverable", "outcome"),
		Dependency:         index.first("dependencies", "dependency status"),
		NonGoals:           requirements.items("non-goals", "non goals"),
		AcceptanceCriteria: countDashboardItems(requirements, "acceptance criteria"),
		OpenQuestions:      countDashboardItems(requirements, "open questions"),
	}
	if result.Mission.Goal == "" {
		result.Mission.Goal = result.Overview
	}
	reasoning := readDashboardMarkdown(filepath.Join(base, "reasoning.md"))
	result.Decisions = reasoning.items("final decisions", "decisions", "decision summary")
	if len(result.Decisions) > 3 {
		result.Decisions = result.Decisions[:3]
	}
	result.UnresolvedRisk = reasoning.first("unresolved risks", "risks", "open questions")
	result.DeferredDecisions = countDashboardItems(reasoning, "deferred", "deferred scope")
	if result.Execute.Total > 0 {
		result.ExecutionPercent = result.Execute.Complete * 100 / result.Execute.Total
	}
	preferred := map[string]bool{"requirements": true, "reasoning": true, "plan": true, "execute": true, "review": true, "smoke": true}
	for _, artifact := range result.Artifacts {
		if preferred[artifact.Label] {
			result.Evidence = append(result.Evidence, artifact)
		}
		if len(result.Evidence) == 3 {
			break
		}
	}
}

func (u *webUseCases) enrichStudyDashboard(result *WebStudyResult) {
	for _, source := range result.Sources {
		result.SourcePreview = append(result.SourcePreview, source)
		if len(result.SourcePreview) == 4 {
			break
		}
	}
	seen := map[string]bool{}
	for _, dimension := range result.Dimensions {
		group := dashboardDimensionGroup(dimension)
		if !seen[group] {
			seen[group] = true
			result.DimensionGroups = append(result.DimensionGroups, group)
		}
		if len(result.DimensionGroups) == 4 {
			break
		}
	}
	for _, task := range result.Tasks {
		if task.Status == "waiting" || task.Status == "retrying" {
			result.Waiting++
		}
	}
	for _, source := range result.SourcePreview {
		row := WebStudyMatrixRow{Source: source}
		for _, group := range result.DimensionGroups {
			status, matched, complete, matchedCount := "pending", false, 0, 0
			for _, task := range result.Tasks {
				if task.Source != source || dashboardDimensionGroup(task.Dimension) != group {
					continue
				}
				matched = true
				matchedCount++
				switch task.Status {
				case "failed", "cancelled":
					status = "failed"
				case "running", "retrying":
					if status != "failed" {
						status = "running"
					}
				case "complete", "completed":
					complete++
				case "inapplicable", "skipped":
					if status == "pending" {
						status = "inapplicable"
					}
				}
			}
			if matched && status == "pending" && complete == matchedCount {
				status = "complete"
			}
			row.Cells = append(row.Cells, WebStudyMatrixCell{Group: group, Status: status})
		}
		result.MatrixRows = append(result.MatrixRows, row)
	}
	for i := len(result.Artifacts) - 1; i >= 0 && len(result.RecentReports) < 3; i-- {
		artifact := result.Artifacts[i]
		if strings.Contains(strings.ToLower(artifact.Label), "report") || strings.Contains(strings.ToLower(artifact.DisplayPath), "report") {
			parsed := readDashboardMarkdown(filepath.Join(u.root, filepath.FromSlash(artifact.DisplayPath)))
			result.RecentReports = append(result.RecentReports, WebReportPreview{Ref: artifact.Ref, Label: artifact.Label, DisplayPath: artifact.DisplayPath, Summary: parsed.first("summary", "synthesis", "finding")})
		}
	}
}

func dashboardDimensionGroup(value string) string {
	if cut := strings.IndexAny(value, "-_. "); cut > 0 {
		return value[:cut]
	}
	return value
}

// annotateStageModels records which model each stage will use when the
// operator leaves the model input empty, plus the model that the most recent
// completed run of each stage actually used. Both come from read-only state:
// the effective planning configuration and sprint runtime metrics.
func (u *webUseCases) annotateStageModels(result *WebSprintResult) {
	for index := range result.RunStages {
		stage := sprint.PlanningStage(result.RunStages[index].Name)
		if runtime, ok := u.dashboard.stageRuntime[stage]; ok {
			result.RunStages[index].ConfiguredModel = strings.TrimSpace(runtime.Model)
		}
	}
	metrics, err := sprint.NewService(u.root).RuntimeMetrics(result.Project, result.Slug)
	if err != nil {
		return
	}
	for _, run := range metrics.Runs {
		if strings.TrimSpace(run.Model) == "" || run.Status != "completed" {
			continue
		}
		for index := range result.RunStages {
			if sprint.PlanningStage(result.RunStages[index].Name) == run.Stage {
				result.RunStages[index].RunModel = run.Model
			}
		}
	}
}

func sprintRunStages(item SprintSummary) []StageSummary {
	stages := append([]StageSummary(nil), item.Stages...)
	executeStatus := "waiting"
	if item.Execute.Available {
		switch {
		case item.Execute.Running > 0:
			executeStatus = "running"
		case item.Execute.Failed > 0:
			executeStatus = "failed"
		case item.Execute.Total > 0 && item.Execute.Complete+item.Execute.Deferred == item.Execute.Total:
			executeStatus = "complete"
		default:
			executeStatus = "ready"
		}
	}
	stages = append(stages, StageSummary{Name: "execute", Status: executeStatus, Error: item.Execute.Message})
	reviewStatus := "waiting"
	if item.Review.Available {
		reviewStatus = item.Review.Status
		if reviewStatus == "" {
			reviewStatus = "ready"
		}
	}
	stages = append(stages, StageSummary{Name: "review", Status: reviewStatus, Error: item.Review.Error})
	smokeStatus := "waiting"
	if item.Smoke.Available {
		smokeStatus = item.Smoke.Status
		if smokeStatus == "" {
			smokeStatus = "ready"
		}
	}
	stages = append(stages, StageSummary{Name: "smoke", Status: smokeStatus, Error: item.Smoke.Error})
	for index := range stages {
		contract := sprint.InputContract(sprint.PlanningStage(stages[index].Name))
		stages[index].PromptContract = &contract
	}
	return stages
}

func (u *webUseCases) Studies(ctx context.Context) (WebStudiesResult, error) {
	items, err := u.dashboard.StudySummaries(ctx)
	if err != nil {
		return WebStudiesResult{}, err
	}
	total := len(items)
	items = bounded(items)
	out := make([]WebStudyResult, 0, len(items))
	for _, item := range items {
		out = append(out, u.webStudy(item))
	}
	return WebStudiesResult{Items: out, CollectionInfo: collectionInfo(len(out), total)}, nil
}

func (u *webUseCases) Study(ctx context.Context, name string) (WebStudyResult, error) {
	items, err := u.dashboard.StudySummaries(ctx)
	if err != nil {
		return WebStudyResult{}, err
	}
	for _, item := range items {
		if item.Name == name {
			result := u.webStudy(item)
			if listing, listErr := study.NewService(u.root).ListStudy(name); listErr == nil {
				if history, histErr := study.LoadRunLoopResourceHistory(listing.Study, 240); histErr == nil {
					throttle := study.SummarizeParallelismThrottle(history)
					result.Parallelism = &ParallelismSummary{Decreased: throttle.Decreased, Events: throttle.Events, RequestedParallelism: throttle.RequestedParallelism, EffectiveParallelism: throttle.EffectiveParallelism}
				}
			}
			u.enrichStudyDashboard(&result)
			return result, nil
		}
	}
	return WebStudyResult{}, ErrWebNotFound
}

func (u *webUseCases) Validations(ctx context.Context, scope, ref string) (WebValidationResult, error) {
	target, ok := u.resolve(ref, scope)
	if !ok {
		return WebValidationResult{}, ErrWebNotFound
	}
	var findings []DisplayFinding
	switch scope {
	case "workspace":
		if err := ctx.Err(); err != nil {
			return WebValidationResult{}, err
		}
		result := workspace.Validate(u.root)
		for _, issue := range result.Issues {
			findings = append(findings, DisplayFinding{Severity: "error", Section: "workspace", Problem: displaySafe(issue)})
		}
	case "project":
		result, err := u.Project(ctx, target.values[0])
		if err != nil {
			return WebValidationResult{}, err
		}
		findings = append(findings, result.Findings...)
	case "sprint":
		result, err := u.Sprint(ctx, target.values[0], target.values[1])
		if err != nil {
			return WebValidationResult{}, err
		}
		findings = append(findings, result.Findings...)
	case "study":
		result, err := u.Study(ctx, target.values[0])
		if err != nil {
			return WebValidationResult{}, err
		}
		findings = append(findings, result.Findings...)
	default:
		return WebValidationResult{}, ErrWebNotFound
	}
	total := len(findings)
	findings = bounded(findings)
	if findings == nil {
		findings = []DisplayFinding{}
	}
	return WebValidationResult{Scope: scope, Ref: ref, Findings: findings, CollectionInfo: collectionInfo(len(findings), total)}, nil
}

func (u *webUseCases) Artifact(ctx context.Context, ref string) (WebArtifactPreview, error) {
	target, ok := u.resolve(ref, "artifact")
	if !ok || len(target.values) != 1 {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	rel := target.values[0]
	if err := ctx.Err(); err != nil {
		return WebArtifactPreview{}, err
	}
	if !supportedPreviewPath(rel) {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	path, err := u.containedArtifactPath(rel)
	if err != nil {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	file, err := os.Open(path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return WebArtifactPreview{}, ErrWebNotFound
		}
		return WebArtifactPreview{}, fmt.Errorf("%w: artifact read", ErrWebUnavailable)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() {
		return WebArtifactPreview{}, ErrWebNotFound
	}
	data, err := io.ReadAll(io.LimitReader(file, WebPreviewByteLimit+1))
	if err != nil {
		return WebArtifactPreview{}, fmt.Errorf("%w: artifact read", ErrWebUnavailable)
	}
	truncated := len(data) > WebPreviewByteLimit
	if truncated {
		data = data[:WebPreviewByteLimit]
	}
	media := mediaTypeForPath(rel)
	return WebArtifactPreview{
		Ref:           ref,
		DisplayPath:   filepath.ToSlash(rel),
		MediaType:     media,
		Content:       string(data),
		SizeBytes:     info.Size(),
		ReturnedBytes: len(data),
		Truncated:     truncated,
		JSONValid:     media != "application/json" || json.Valid(data),
	}, nil
}

func (u *webUseCases) Health(ctx context.Context) (WebHealthResult, error) {
	if err := ctx.Err(); err != nil {
		return WebHealthResult{}, err
	}
	info, err := os.Stat(filepath.Join(u.root, workspace.MarkerFile))
	available := err == nil && !info.IsDir()
	status := "ok"
	if !available {
		status = "unavailable"
	}
	return WebHealthResult{Status: status, Server: true, Workspace: available}, nil
}

func (u *webUseCases) webProject(item ProjectSummary, sprints []WebSprintResult) WebProjectResult {
	docs := append([]string(nil), item.MarkdownDocs...)
	if docs == nil {
		docs = []string{}
	}
	findings := bounded(append([]DisplayFinding(nil), item.Findings...))
	if findings == nil {
		findings = []DisplayFinding{}
	}
	return WebProjectResult{
		Ref:       u.issue("project", item.Name),
		Name:      item.Name,
		Docs:      docs,
		Findings:  findings,
		Artifacts: u.webArtifacts(item.Artifacts),
		Sprints:   nonNil(sprints),
	}
}

func (u *webUseCases) webSprint(item SprintSummary) WebSprintResult {
	stages := append([]StageSummary(nil), item.Stages...)
	if stages == nil {
		stages = []StageSummary{}
	}
	findings := bounded(append([]DisplayFinding(nil), item.Findings...))
	if findings == nil {
		findings = []DisplayFinding{}
	}
	result := WebSprintResult{
		Ref:        u.issue("sprint", item.Project, item.Slug),
		Project:    item.Project,
		Slug:       item.Slug,
		Status:     item.Status,
		Assessment: item.Assessment,
		NextAction: displaySafe(item.NextAction),
		Stages:     stages,
		Execute:    item.Execute,
		Review:     item.Review,
		Smoke:      item.Smoke,
		QA:         item.QA,
		Findings:   findings,
		Artifacts:  u.webArtifacts(item.Artifacts),
	}
	result.ExecuteHealth = "waiting"
	switch {
	case item.Execute.Failed > 0:
		result.ExecuteHealth = "failed"
	case item.Execute.Running > 0:
		result.ExecuteHealth = "running"
	case item.Execute.Total > 0 && item.Execute.Complete+item.Execute.Deferred == item.Execute.Total:
		result.ExecuteHealth = "complete"
	}
	result.ReviewHealth = "waiting"
	switch {
	case item.Review.Stale:
		result.ReviewHealth = "stale"
	case item.Review.Failed > 0:
		result.ReviewHealth = "failed"
	case item.Review.Status == "complete" || item.Review.Status == "completed":
		result.ReviewHealth = "complete"
	case item.Review.Running > 0:
		result.ReviewHealth = "running"
	}
	result.SmokeHealth = "waiting"
	switch {
	case item.Smoke.Stale:
		result.SmokeHealth = "stale"
	case item.Smoke.Status == "failed" || item.Smoke.Verdict == "fail":
		result.SmokeHealth = "failed"
	case item.Smoke.Status == "complete" || item.Smoke.Status == "completed":
		result.SmokeHealth = "complete"
	case item.Smoke.Status == "running":
		result.SmokeHealth = "running"
	}
	return result
}

func (u *webUseCases) webStudy(item StudySummary) WebStudyResult {
	findings := bounded(append([]DisplayFinding(nil), item.Findings...))
	if findings == nil {
		findings = []DisplayFinding{}
	}
	retried := make([]WebStudyTaskRetry, 0, len(item.Tasks))
	for _, task := range item.Tasks {
		if task.Retries == 0 && task.Status != "retrying" {
			continue
		}
		retries := task.Retries
		if retries == 0 {
			retries = 1
		}
		retried = append(retried, WebStudyTaskRetry{ID: task.ID, Kind: task.Kind, Status: task.Status, Retries: retries, SessionReuse: task.SessionReuse})
	}
	if retried == nil {
		retried = []WebStudyTaskRetry{}
	}
	return WebStudyResult{
		Ref:          u.issue("study", item.Name),
		Name:         item.Name,
		Sources:      nonNil(append([]string(nil), item.Sources...)),
		Dimensions:   nonNil(append([]string(nil), item.Dimensions...)),
		Status:       item.Status,
		RunID:        displaySafe(item.RunID),
		Total:        item.Total,
		Completed:    item.Completed,
		Failed:       item.Failed,
		RunActive:    item.RunActive,
		ActiveTasks:  item.ActiveTasks,
		Pending:      item.Pending,
		Cancelled:    item.Cancelled,
		Retries:      item.Retries,
		RetriedTasks: retried,
		Tasks:        append([]RunTaskSummary(nil), item.Tasks...),
		Findings:     findings,
		Artifacts:    u.webArtifacts(item.Artifacts),
	}
}

func (u *webUseCases) webArtifacts(items []DisplayArtifact) []WebArtifactLink {
	out := make([]WebArtifactLink, 0, len(items))
	for _, item := range items {
		rel := filepath.ToSlash(filepath.Clean(filepath.FromSlash(item.Path)))
		if filepath.IsAbs(rel) || !supportedPreviewPath(rel) {
			continue
		}
		out = append(out, WebArtifactLink{
			Ref:         u.issue("artifact", rel),
			Label:       item.Label,
			DisplayPath: rel,
			MediaType:   mediaTypeForPath(rel),
		})
		if len(out) == WebCollectionLimit {
			break
		}
	}
	if out == nil {
		return []WebArtifactLink{}
	}
	return out
}

func (u *webUseCases) issue(kind string, values ...string) string {
	mac := hmac.New(sha256.New, u.secret[:])
	_, _ = mac.Write([]byte(kind))
	for _, value := range values {
		_, _ = mac.Write([]byte{0})
		_, _ = mac.Write([]byte(value))
	}
	ref := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
	target := webRefTarget{kind: kind, values: append([]string(nil), values...)}
	u.mu.Lock()
	u.refs[ref] = target
	u.mu.Unlock()
	return ref
}

func (u *webUseCases) resolve(ref, kind string) (webRefTarget, bool) {
	u.mu.RLock()
	target, ok := u.refs[ref]
	u.mu.RUnlock()
	return target, ok && target.kind == kind
}

func (u *webUseCases) containedArtifactPath(rel string) (string, error) {
	path, err := workspace.ResolveInside(u.root, rel)
	if err != nil {
		return "", err
	}
	root, err := filepath.EvalSymlinks(u.root)
	if err != nil {
		return "", err
	}
	path, err = filepath.EvalSymlinks(path)
	if err != nil {
		return "", err
	}
	inside, err := filepath.Rel(root, path)
	if err != nil || inside == ".." || strings.HasPrefix(inside, ".."+string(filepath.Separator)) {
		return "", errors.New("artifact escapes workspace")
	}
	return path, nil
}

func mediaTypeForPath(path string) string {
	if strings.EqualFold(filepath.Ext(path), ".json") {
		return "application/json"
	}
	return "text/markdown"
}

func bounded[T any](items []T) []T {
	if len(items) > WebCollectionLimit {
		items = items[:WebCollectionLimit]
	}
	return items
}

func nonNil[T any](items []T) []T {
	if items == nil {
		return []T{}
	}
	return items
}

func collectionInfo(returned, total int) CollectionInfo {
	return CollectionInfo{ReturnedCount: returned, TotalCount: total, Truncated: returned < total}
}

package app

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
)

type durableOperationManager struct {
	repository runcontrol.Repository
	owner      runcontrol.Owner
	mu         sync.Mutex
	owned      map[string]*ownedDurableOperation
}

type ownedDurableOperation struct {
	fence        runcontrol.Fence
	cancel       context.CancelFunc
	stop         chan struct{}
	done         chan struct{}
	eventMu      sync.Mutex
	progressKey  string
	progressAt   time.Time
	omitted      uint64
	omittedFirst time.Time
	omittedLast  time.Time
}

// durableCLICommand is the synchronous CLI counterpart to the web/TUI
// acceptance boundary. It keeps the manager alive for the whole command and
// gives product code the cancellation-aware context owned by the durable run.
type durableCLICommand struct {
	manager  *durableOperationManager
	accepted AcceptedOperation
}

type durableOperationContextKey struct{}

type durableOperationOwnership struct {
	repository runcontrol.Repository
	fence      runcontrol.Fence
}

func beginDurableCLICommand(deps dependencies, request OperationRequest) (*durableCLICommand, error) {
	repository, _, err := runRepository(deps)
	if err != nil {
		return nil, err
	}
	manager := newDurableOperationManager(repository, deps.runControl.owner)
	accepted, err := manager.AcceptOperation(deps.ctx, Confirmation{Request: request}, "")
	if err != nil {
		return nil, classifiedCause(ExitRuntime, err, "run-control.accept")
	}
	return &durableCLICommand{manager: manager, accepted: accepted}, nil
}

func (c *durableCLICommand) Context() context.Context { return c.accepted.Context }

func (c *durableCLICommand) QAWriterToken() (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	if c == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is unavailable")
	}
	return qaOwnershipFromContext(c.accepted.Context)
}

func (c *durableCLICommand) Finish(runErr error) error {
	state := OperationComplete
	if c.accepted.Context.Err() != nil {
		state = OperationCancelled
	} else if runErr != nil {
		state = OperationFailed
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := c.manager.FinishOperation(ctx, c.accepted.RunID, state, runErr); err != nil {
		return classifiedCause(ExitRuntime, err, "run-control.finish")
	}
	return nil
}

func finishDurableCLICommand(command *durableCLICommand, runErr error) error {
	if command == nil {
		return runErr
	}
	return errors.Join(runErr, command.Finish(runErr))
}

func newDurableOperationManager(repository runcontrol.Repository, owner runcontrol.Owner) *durableOperationManager {
	return &durableOperationManager{repository: repository, owner: owner, owned: make(map[string]*ownedDurableOperation)}
}

func (m *durableOperationManager) AcceptOperation(ctx context.Context, confirmation Confirmation, digest string) (AcceptedOperation, error) {
	req := confirmation.Request
	target := runcontrol.Target{
		Kind: "operation", Operation: string(req.Kind), Project: req.Project, Sprint: req.Sprint,
		Study: req.Study, Stage: req.Stage, Task: req.Task,
	}
	snapshot, err := m.repository.Accept(ctx, runcontrol.Acceptance{
		Target: target, ProductStatus: "prepared", OperationAlias: digest, ConfirmationDigest: digest,
	})
	if err != nil && digest != "" && errors.Is(err, runcontrol.ErrConflict) {
		existing, resolveErr := m.repository.ResolveOperationAlias(ctx, digest)
		if resolveErr != nil {
			return AcceptedOperation{}, errors.Join(err, resolveErr)
		}
		return AcceptedOperation{RunID: string(existing.RunID), Context: ctx, Existing: true, Lifecycle: string(existing.Lifecycle)}, nil
	}
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation acceptance: %w", err)
	}
	attempt, _, err := m.repository.Claim(ctx, runcontrol.Claim{RunID: snapshot.RunID, Owner: m.owner, Lease: runcontrol.OwnerLeaseDuration})
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation owner claim: %w", err)
	}
	fence := runcontrol.Fence{RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: m.owner.ID, FencingGeneration: attempt.FencingGeneration}
	if _, _, err := appendRunEventWithRetry(ctx, m.repository, fence, runcontrol.EventDraft{
		Type: runcontrol.EventLifecycle, Lifecycle: runcontrol.LifecycleRunning,
		Payload: map[string]string{"lifecycle": string(runcontrol.LifecycleRunning)},
	}); err != nil {
		terminalCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, _ = proposeRunTerminalWithRetry(terminalCtx, m.repository, fence, runcontrol.TerminalProposal{Outcome: runcontrol.TerminalPersistenceLost, Reason: "operation start persistence failed", ProposedBy: m.owner.ID})
		cancel()
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation start: %w", err)
	}
	operationCtx, cancel := context.WithCancel(runcontrol.WithParentRun(ctx, snapshot.RunID))
	operationCtx = context.WithValue(operationCtx, durableOperationContextKey{}, durableOperationOwnership{repository: m.repository, fence: fence})
	owned := &ownedDurableOperation{fence: fence, cancel: cancel, stop: make(chan struct{}), done: make(chan struct{})}
	m.mu.Lock()
	m.owned[string(snapshot.RunID)] = owned
	m.mu.Unlock()
	go m.controlOperation(operationCtx, owned)
	return AcceptedOperation{RunID: string(snapshot.RunID), Context: operationCtx, Lifecycle: string(runcontrol.LifecycleRunning)}, nil
}

func qaOwnershipFromContext(ctx context.Context) (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	ownership, ok := ctx.Value(durableOperationContextKey{}).(durableOperationOwnership)
	if !ok || ownership.repository == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is missing from the operation context")
	}
	token := sprint.QAWriterToken{RunID: string(ownership.fence.RunID), OperationalAttemptID: string(ownership.fence.AttemptID), FencingGeneration: ownership.fence.FencingGeneration}
	fence := func(got sprint.QAWriterToken) error {
		if got != token {
			return runcontrol.ErrStaleFence
		}
		fenceCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer cancel()
		_, err := ownership.repository.Heartbeat(fenceCtx, ownership.fence, runControlLease)
		return err
	}
	return token, fence, nil
}

func (m *durableOperationManager) RecordOperationEvent(ctx context.Context, runID string, event OperationEvent) (bool, error) {
	m.mu.Lock()
	owned := m.owned[runID]
	m.mu.Unlock()
	if owned == nil {
		return false, runcontrol.ErrNotFound
	}
	owned.eventMu.Lock()
	defer owned.eventMu.Unlock()
	eventType := runcontrol.EventProgress
	if event.State == OperationFailed {
		eventType = runcontrol.EventWarning
	}
	key := string(eventType) + "\x00" + event.Stage + "\x00" + event.Task + "\x00" + event.PhaseState + "\x00" + event.SafeSummary + "\x00" + event.EventType + "\x00" + event.EventKind + "\x00" + event.Tool + "\x00" + event.Reason + "\x00" + event.Detail
	now := time.Now().UTC()
	elapsed := now.Sub(owned.progressAt)
	if eventType == runcontrol.EventProgress && key == owned.progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
		if owned.omitted == 0 {
			owned.omittedFirst = now
		}
		owned.omitted++
		owned.omittedLast = now
		return false, nil
	}
	payload := map[string]string{
		"state": string(event.State), "type": event.EventType,
		"count": fmt.Sprintf("%d/%d", event.Completed, event.Total),
	}
	for key, value := range map[string]string{
		"phase_state": event.PhaseState, "summary": event.SafeSummary,
		"tool_call_id": event.ToolCallID, "tool_status": event.ToolStatus,
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"provider": event.Provider, "model": event.Model, "harness": event.Harness,
	} {
		if value != "" {
			payload[key] = value
		}
	}
	var omission *runcontrol.Omission
	if event.Message != "" {
		omission = &runcontrol.Omission{Reason: "presentation message omitted", Count: 1}
	}
	if owned.omitted > 0 {
		if omission == nil {
			omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
		}
		omission.Count += owned.omitted
		omission.FirstAt, omission.LastAt = &owned.omittedFirst, &owned.omittedLast
		owned.omitted = 0
	}
	_, _, err := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeOperation, Stage: event.Stage, Task: event.Task,
		Kind: event.EventKind, Tool: event.Tool, Action: event.Action, Reason: event.Reason,
		Detail: event.Detail, Payload: payload, Omission: omission,
	})
	if err != nil {
		owned.cancel()
		return false, err
	}
	if eventType == runcontrol.EventProgress {
		owned.progressKey, owned.progressAt = key, now
	}
	return true, nil
}

func (m *durableOperationManager) controlOperation(ctx context.Context, owned *ownedDurableOperation) {
	defer close(owned.done)
	ticker := time.NewTicker(runcontrol.OwnerTickInterval)
	defer ticker.Stop()
	lastHeartbeat, lastReconcile := time.Now(), time.Now()
	for {
		select {
		case <-ctx.Done():
			return
		case <-owned.stop:
			return
		case now := <-ticker.C:
			snapshot, err := m.repository.Snapshot(ctx, owned.fence.RunID)
			if err != nil {
				owned.cancel()
				return
			}
			if snapshot.Cancellation.State == runcontrol.CancellationRequested {
				if _, _, err := m.repository.AcknowledgeCancellation(ctx, owned.fence); err != nil {
					owned.cancel()
					return
				}
				owned.cancel()
				return
			}
			if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
				if _, err := m.repository.Heartbeat(ctx, owned.fence, runcontrol.OwnerLeaseDuration); err != nil {
					owned.cancel()
					return
				}
				lastHeartbeat = now
			}
			if now.Sub(lastReconcile) >= runcontrol.ReconciliationInterval {
				if _, err := m.repository.Reconcile(ctx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
					owned.cancel()
					return
				}
				lastReconcile = now
			}
		}
	}
}

func (m *durableOperationManager) FinishOperation(ctx context.Context, runID string, state OperationState, runErr error) error {
	m.mu.Lock()
	owned := m.owned[runID]
	delete(m.owned, runID)
	m.mu.Unlock()
	if owned == nil {
		return nil
	}
	owned.eventMu.Lock()
	if owned.omitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{Type: runcontrol.EventOmission, Omission: &runcontrol.Omission{Reason: "equivalent progress coalesced", Count: owned.omitted, FirstAt: &owned.omittedFirst, LastAt: &owned.omittedLast}})
		if appendErr != nil && runErr == nil {
			runErr = appendErr
		}
		owned.omitted = 0
	}
	owned.eventMu.Unlock()
	close(owned.stop)
	<-owned.done
	owned.cancel()
	outcome := runcontrol.TerminalSucceeded
	reason := "operation completed"
	switch {
	case errors.Is(runErr, context.DeadlineExceeded):
		outcome, reason = runcontrol.TerminalTimedOut, "operation deadline exceeded"
	case errors.Is(runErr, context.Canceled), state == OperationCancelled:
		outcome, reason = runcontrol.TerminalCancelled, "operation cancelled"
	case runErr != nil, state == OperationFailed:
		outcome, reason = runcontrol.TerminalFailed, "operation failed"
	case state == OperationPartial:
		outcome, reason = runcontrol.TerminalInterrupted, "operation interrupted"
	}
	_, _, err := proposeRunTerminalWithRetry(ctx, m.repository, owned.fence, runcontrol.TerminalProposal{Outcome: outcome, Reason: reason, ProposedBy: m.owner.ID})
	return err
}

package web

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/app"
)

const (
	MaxActiveOperations        = 8
	MaxPreparations            = 128
	PreparationTTL             = 2 * time.Minute
	MaxEventsPerOperation      = 256
	MaxEventBytesPerOperation  = 256 * 1024
	MaxEncodedEventBytes       = 16 * 1024
	MaxTerminalResultBytes     = 256 * 1024
	MaxSubscribersPerOperation = 8
	MaxConcurrentStreams       = 32
	SubscriberQueueSize        = 32
	TerminalRetention          = 10 * time.Minute
	SSEHeartbeat               = 15 * time.Second
	MaxStreamLifetime          = 30 * time.Minute
)

var (
	errOperationCapacity  = errors.New("operation capacity reached")
	errSubscriberCapacity = errors.New("subscriber capacity reached")
	errServerDraining     = errors.New("server draining")
	errOperationNotFound  = errors.New("operation not found")
)

type operationDocument struct {
	ID            string              `json:"id"`
	Kind          app.OperationKind   `json:"kind"`
	State         string              `json:"state"`
	Reason        string              `json:"reason,omitempty"`
	CreatedAt     time.Time           `json:"created_at"`
	StartedAt     *time.Time          `json:"started_at,omitempty"`
	FinishedAt    *time.Time          `json:"finished_at,omitempty"`
	LastEventID   string              `json:"last_event_id"`
	DurableStatus durableStatusDTO    `json:"durable_status"`
	Result        *operationResultDTO `json:"result,omitempty"`
}

type activeOperationDTO struct {
	ID        string            `json:"id"`
	Kind      app.OperationKind `json:"kind"`
	State     string            `json:"state"`
	Project   string            `json:"project,omitempty"`
	Sprint    string            `json:"sprint,omitempty"`
	Study     string            `json:"study,omitempty"`
	StartedAt *time.Time        `json:"started_at,omitempty"`
}

type durableStatusDTO struct {
	Available   bool   `json:"available"`
	RefreshPath string `json:"refresh_path,omitempty"`
}

type operationResultDTO struct {
	State     string       `json:"state"`
	Subject   string       `json:"subject,omitempty"`
	Message   string       `json:"message,omitempty"`
	Content   string       `json:"content,omitempty"`
	Truncated bool         `json:"truncated,omitempty"`
	Findings  []findingDTO `json:"findings,omitempty"`
	Error     *errorBody   `json:"error,omitempty"`
}

type operationEvent struct {
	ID   uint64
	Name string
	Data []byte
}

type operationSubscriber struct {
	id uint64
	ch chan operationEvent
}

type operationRecord struct {
	doc         operationDocument
	session     string
	request     app.OperationRequest
	cancel      context.CancelFunc
	cancelOnce  sync.Once
	done        chan struct{}
	nextEventID uint64
	events      []operationEvent
	eventBytes  int
	subscribers map[uint64]*operationSubscriber
	nextSubID   uint64
	dedupKey    string
}

type operationHub struct {
	rootCtx context.Context
	ops     app.WebOperations
	now     func() time.Time
	id      func() string

	mu       sync.Mutex
	records  map[string]*operationRecord
	dedup    map[string]string
	active   int
	streams  int
	draining bool
	counters operationCounters
}

type operationCounters struct {
	starts             atomic.Int64
	active             atomic.Int64
	terminal           atomic.Int64
	capacityRejections atomic.Int64
	cancellations      atomic.Int64
	activeStreams      atomic.Int64
	slowSubscribers    atomic.Int64
	replayGaps         atomic.Int64
	projectionDrops    atomic.Int64
	shutdownCleanups   atomic.Int64
}

func newOperationHub(rootCtx context.Context, ops app.WebOperations, now func() time.Time, id func() string) *operationHub {
	if rootCtx == nil {
		rootCtx = context.Background()
	}
	if now == nil {
		now = time.Now
	}
	if id == nil {
		id = randomRequestID
	}
	return &operationHub{rootCtx: rootCtx, ops: ops, now: now, id: id, records: make(map[string]*operationRecord), dedup: make(map[string]string)}
}

func (h *operationHub) start(session string, prepared app.Confirmation) (operationDocument, error) {
	return h.startConfirmed(session, "", func() (app.Confirmation, error) { return prepared, nil })
}

func (h *operationHub) startConfirmed(session, dedupKey string, confirm func() (app.Confirmation, error)) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	if id := h.dedup[dedupKey]; dedupKey != "" && id != "" {
		if record := h.records[id]; record != nil && record.session == session {
			return cloneOperationDocument(record.doc), nil
		}
		delete(h.dedup, dedupKey)
	}
	if h.draining {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errServerDraining
	}
	if h.active >= MaxActiveOperations {
		h.counters.capacityRejections.Add(1)
		return operationDocument{}, errOperationCapacity
	}
	if h.ops == nil {
		return operationDocument{}, errors.New("operation capability unavailable")
	}
	prepared, err := confirm()
	if err != nil {
		return operationDocument{}, err
	}
	id := "op_" + h.id()
	for h.records[id] != nil {
		id = "op_" + h.id()
	}
	created := h.now().UTC()
	ctx, cancel := context.WithCancel(h.rootCtx)
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		accepted, acceptErr := manager.AcceptOperation(ctx, prepared, dedupKey)
		if acceptErr != nil {
			if !errors.Is(acceptErr, app.ErrWebUnavailable) {
				cancel()
				return operationDocument{}, acceptErr
			}
		} else {
			id = accepted.RunID
			if accepted.Context != nil {
				ctx = accepted.Context
			}
			if accepted.Existing {
				doc := operationDocument{ID: id, Kind: prepared.Request.Kind, State: accepted.Lifecycle, CreatedAt: created, DurableStatus: durableStatusDTO{Available: true, RefreshPath: "/runs/" + id}}
				cancel()
				return doc, nil
			}
		}
	}
	record := &operationRecord{
		doc: operationDocument{
			ID: id, Kind: prepared.Request.Kind, State: "accepted", CreatedAt: created,
			DurableStatus: durableStatusDTO{Available: prepared.DurableRefreshPath != "", RefreshPath: prepared.DurableRefreshPath},
		},
		session: session, request: prepared.Request, cancel: cancel, done: make(chan struct{}),
		subscribers: make(map[uint64]*operationSubscriber), dedupKey: dedupKey,
	}
	h.records[id] = record
	if dedupKey != "" {
		h.dedup[dedupKey] = id
	}
	h.active++
	h.counters.starts.Add(1)
	h.counters.active.Add(1)
	h.appendEventLocked(record, "snapshot", map[string]any{"state": "accepted"})
	doc := cloneOperationDocument(record.doc)
	go h.run(ctx, record)
	return doc, nil
}

func (h *operationHub) run(ctx context.Context, record *operationRecord) {
	started := h.now().UTC()
	h.mu.Lock()
	if record.doc.State == "accepted" {
		record.doc.State = "running"
		record.doc.StartedAt = &started
		h.appendEventLocked(record, "progress", map[string]any{"message": "operation started", "state": "running"})
	}
	h.mu.Unlock()

	result, runErr := h.ops.RunOperation(ctx, record.request, func(event app.OperationEvent) {
		h.publishAppEvent(record, event)
	})
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		finishCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		finishErr := manager.FinishOperation(finishCtx, record.doc.ID, result.State, runErr)
		cancel()
		if finishErr != nil && !errors.Is(finishErr, app.ErrWebUnavailable) {
			runErr = errors.Join(runErr, finishErr)
		}
	}
	h.finish(record, result, runErr)
}

func (h *operationHub) publishAppEvent(record *operationRecord, event app.OperationEvent) {
	if manager, ok := h.ops.(app.DurableOperationManager); ok {
		committed, err := manager.RecordOperationEvent(context.Background(), record.doc.ID, event)
		if err != nil && !errors.Is(err, app.ErrWebUnavailable) {
			record.cancel()
			return
		}
		if err == nil && !committed {
			return
		}
	}
	name := "progress"
	if event.State == app.OperationFailed {
		name = "warning"
	}
	payload := map[string]any{
		"state": string(event.State), "stage": safeWebText(event.Stage), "task": safeWebText(event.Task),
		"message": safeWebText(event.Message), "completed": event.Completed, "total": event.Total, "attempt": event.Attempt,
		"event_kind": safeWebText(event.EventKind), "event_type": safeWebText(event.EventType), "tool": safeWebText(event.Tool), "action": safeWebText(event.Action),
		"tool_call_id": safeWebText(event.ToolCallID), "tool_status": safeWebText(event.ToolStatus),
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"reason": safeWebText(event.Reason), "detail": safeWebText(event.Detail),
		"runtime_attempts": event.RuntimeAttempts, "turns": event.Turns, "turns_known": event.TurnsKnown,
		"tokens": event.Tokens, "tokens_known": event.TokensKnown, "duration": safeWebText(event.Duration),
		"provider": safeWebText(event.Provider), "model": safeWebText(event.Model), "harness": safeWebText(event.Harness), "cost": safeWebText(event.Cost), "runtime_events": event.RuntimeEvents,
	}
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	h.appendEventLocked(record, name, payload)
}

func (h *operationHub) finish(record *operationRecord, result app.OperationResult, runErr error) {
	finished := h.now().UTC()
	h.mu.Lock()
	defer h.mu.Unlock()
	if terminalOperationState(record.doc.State) {
		return
	}
	state := "succeeded"
	switch {
	case errors.Is(runErr, context.Canceled), result.State == app.OperationCancelled:
		state = "cancelled"
	case runErr != nil, result.State == app.OperationFailed:
		state = "failed"
	case result.State == app.OperationPartial:
		state = "interrupted"
	}
	record.doc.State = state
	record.doc.FinishedAt = &finished
	record.doc.Result = projectOperationResult(result)
	h.appendEventLocked(record, "terminal", map[string]any{"state": state, "reason": record.doc.Reason, "result": record.doc.Result})
	h.active--
	h.counters.active.Add(-1)
	h.counters.terminal.Add(1)
	close(record.done)
	for id, subscriber := range record.subscribers {
		close(subscriber.ch)
		delete(record.subscribers, id)
		h.streams--
		h.counters.activeStreams.Add(-1)
	}
}

func (h *operationHub) status(session, id string) (operationDocument, error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return operationDocument{}, errOperationNotFound
	}
	return cloneOperationDocument(record.doc), nil
}

func (h *operationHub) activeOperations(session string) []activeOperationDTO {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	result := make([]activeOperationDTO, 0, h.active)
	for _, record := range h.records {
		if record.session != session || terminalOperationState(record.doc.State) {
			continue
		}
		result = append(result, activeOperationDTO{
			ID: record.doc.ID, Kind: record.doc.Kind, State: record.doc.State,
			Project: record.request.Project, Sprint: record.request.Sprint, Study: record.request.Study,
			StartedAt: record.doc.StartedAt,
		})
	}
	sort.Slice(result, func(i, j int) bool {
		left, right := result[i].StartedAt, result[j].StartedAt
		if left == nil || right == nil {
			return left != nil
		}
		return left.After(*right)
	})
	return result
}

func (h *operationHub) cancelOperation(session, id, reason string) (operationDocument, bool, error) {
	h.mu.Lock()
	record := h.records[id]
	if record == nil || (session != "" && record.session != session) {
		h.mu.Unlock()
		return operationDocument{}, false, errOperationNotFound
	}
	if terminalOperationState(record.doc.State) {
		doc := cloneOperationDocument(record.doc)
		h.mu.Unlock()
		return doc, false, nil
	}
	requested := false
	record.cancelOnce.Do(func() {
		requested = true
		record.doc.State = "cancelling"
		record.doc.Reason = canonicalCancelReason(reason)
		h.appendEventLocked(record, "cancel_requested", map[string]any{"reason": record.doc.Reason})
	})
	doc := cloneOperationDocument(record.doc)
	cancel := record.cancel
	h.mu.Unlock()
	if requested {
		h.counters.cancellations.Add(1)
		cancel()
	}
	return doc, requested, nil
}

func (h *operationHub) subscribe(session, id string, lastID uint64) ([]operationEvent, <-chan operationEvent, func(), error) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.reapLocked()
	record := h.records[id]
	if record == nil || record.session != session {
		return nil, nil, nil, errOperationNotFound
	}
	if h.streams >= MaxConcurrentStreams || len(record.subscribers) >= MaxSubscribersPerOperation {
		h.counters.capacityRejections.Add(1)
		return nil, nil, nil, errSubscriberCapacity
	}
	if lastID > 0 && len(record.events) > 0 && lastID < record.events[0].ID-1 {
		h.counters.replayGaps.Add(1)
		h.appendEventLocked(record, "recovery_required", map[string]any{
			"oldest_retained_id": strconv.FormatUint(record.events[0].ID, 10),
			"newest_retained_id": strconv.FormatUint(record.nextEventID, 10),
			"refresh_path":       record.doc.DurableStatus.RefreshPath,
		})
		h.appendEventLocked(record, "snapshot", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
	}
	replay := make([]operationEvent, 0, len(record.events))
	for _, event := range record.events {
		if event.ID > lastID {
			replay = append(replay, event)
		}
	}
	record.nextSubID++
	sub := &operationSubscriber{id: record.nextSubID, ch: make(chan operationEvent, SubscriberQueueSize)}
	if terminalOperationState(record.doc.State) {
		close(sub.ch)
	} else {
		record.subscribers[sub.id] = sub
		h.streams++
		h.counters.activeStreams.Add(1)
	}
	var once sync.Once
	unsubscribe := func() {
		once.Do(func() {
			h.mu.Lock()
			defer h.mu.Unlock()
			if current, ok := record.subscribers[sub.id]; ok {
				delete(record.subscribers, sub.id)
				h.streams--
				h.counters.activeStreams.Add(-1)
				close(current.ch)
			}
		})
	}
	return replay, sub.ch, unsubscribe, nil
}

func (h *operationHub) appendEventLocked(record *operationRecord, name string, payload any) {
	name = stableOperationEventName(name)
	record.nextEventID++
	body := map[string]any{
		"operation_id": record.doc.ID,
		"time":         h.now().UTC().Format(time.RFC3339Nano),
		"sequence":     record.nextEventID,
		"payload":      payload,
	}
	data, err := json.Marshal(body)
	if err != nil {
		h.counters.projectionDrops.Add(1)
		return
	}
	if len(data) > MaxEncodedEventBytes {
		data, _ = json.Marshal(map[string]any{
			"operation_id": record.doc.ID, "time": h.now().UTC().Format(time.RFC3339Nano),
			"sequence": record.nextEventID, "payload": map[string]any{"message": "event projection exceeded the safe size limit"},
		})
		name = "warning"
	}
	event := operationEvent{ID: record.nextEventID, Name: name, Data: data}
	record.events = append(record.events, event)
	record.eventBytes += len(data)
	for len(record.events) > MaxEventsPerOperation || record.eventBytes > MaxEventBytesPerOperation {
		record.eventBytes -= len(record.events[0].Data)
		record.events = record.events[1:]
	}
	record.doc.LastEventID = strconv.FormatUint(event.ID, 10)
	for id, subscriber := range record.subscribers {
		select {
		case subscriber.ch <- event:
		default:
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
			h.counters.slowSubscribers.Add(1)
		}
	}
}

func stableOperationEventName(name string) string {
	switch name {
	case "snapshot", "progress", "warning", "finding", "artifact", "cancel_requested", "recovery_required", "terminal":
		return name
	default:
		return "progress"
	}
}

func (h *operationHub) drainAndWait(ctx context.Context) error {
	h.mu.Lock()
	h.draining = true
	var records []*operationRecord
	for _, record := range h.records {
		if !terminalOperationState(record.doc.State) {
			records = append(records, record)
		}
	}
	h.mu.Unlock()
	for _, record := range records {
		_, _, _ = h.cancelOperation("", record.doc.ID, "server_shutdown")
	}
	h.counters.shutdownCleanups.Add(int64(len(records)))
	for _, record := range records {
		select {
		case <-record.done:
		case <-ctx.Done():
			persistErr := h.persistCleanupUncertain(records)
			h.markCleanupUncertain(records)
			return errors.Join(ctx.Err(), persistErr)
		}
	}
	return nil
}

func (h *operationHub) persistCleanupUncertain(records []*operationRecord) error {
	recorder, ok := h.ops.(app.OperationCleanupRecorder)
	if !ok {
		return errors.New("operation capability cannot persist cleanup uncertainty")
	}
	var result error
	for _, record := range records {
		h.mu.Lock()
		terminal := terminalOperationState(record.doc.State)
		h.mu.Unlock()
		if terminal {
			continue
		}
		persistCtx, cancel := context.WithTimeout(context.Background(), time.Second)
		err := recorder.RecordOperationCleanupUncertain(persistCtx, app.OperationCleanupUncertain{
			OperationID: record.doc.ID,
			Request:     record.request,
			Reason:      "server_shutdown",
			RecordedAt:  h.now().UTC(),
		})
		cancel()
		if err != nil {
			result = errors.Join(result, fmt.Errorf("persist cleanup uncertainty for %s: %w", record.doc.ID, err))
		}
	}
	return result
}

func (h *operationHub) markCleanupUncertain(records []*operationRecord) {
	h.mu.Lock()
	defer h.mu.Unlock()
	finished := h.now().UTC()
	for _, record := range records {
		if terminalOperationState(record.doc.State) {
			continue
		}
		record.doc.State = "cleanup_uncertain"
		record.doc.Reason = "server_shutdown"
		record.doc.FinishedAt = &finished
		record.doc.Result = &operationResultDTO{State: "cleanup_uncertain", Message: "Cleanup did not finish before the shutdown deadline. Refresh durable status before retrying."}
		h.appendEventLocked(record, "terminal", map[string]any{"state": record.doc.State, "reason": record.doc.Reason})
		h.active--
		h.counters.active.Add(-1)
		h.counters.terminal.Add(1)
		close(record.done)
		for id, subscriber := range record.subscribers {
			close(subscriber.ch)
			delete(record.subscribers, id)
			h.streams--
			h.counters.activeStreams.Add(-1)
		}
	}
}

func (h *operationHub) isDraining() bool {
	h.mu.Lock()
	defer h.mu.Unlock()
	return h.draining
}

func (h *operationHub) reapLocked() {
	now := h.now().UTC()
	for id, record := range h.records {
		if record.doc.FinishedAt != nil && now.Sub(*record.doc.FinishedAt) >= TerminalRetention {
			delete(h.records, id)
			if record.dedupKey != "" {
				delete(h.dedup, record.dedupKey)
			}
		}
	}
}

func projectOperationResult(result app.OperationResult) *operationResultDTO {
	out := &operationResultDTO{
		State: safeWebText(string(result.State)), Subject: safeWebText(result.Subject), Message: safeWebText(result.Message),
		Content: safeProjectedText(result.Content, MaxTerminalResultBytes/2), Truncated: result.Truncated,
	}
	for _, finding := range result.Findings {
		out.Findings = append(out.Findings, findingDTO{
			Severity: safeWebText(finding.Severity), Section: safeWebText(finding.Section), Problem: safeWebText(finding.Problem),
			Cause: safeWebText(finding.Cause), Suggestion: safeWebText(finding.Suggestion),
		})
	}
	if result.Error != nil {
		out.Error = &errorBody{Code: safeWebText(result.Error.Code), Message: safeWebText(result.Error.Message), Retryable: result.Error.Retryable, Details: map[string]any{
			"category": safeWebText(result.Error.Category), "component": safeWebText(result.Error.Component), "cause": safeWebText(result.Error.Cause), "guidance": safeWebText(result.Error.Guidance),
		}}
	}
	if data, _ := json.Marshal(out); len(data) > MaxTerminalResultBytes {
		out.Content = ""
		out.Findings = nil
		out.Truncated = true
		out.Message = safeBoundedText(out.Message, 4096)
	}
	return out
}

func cloneOperationDocument(doc operationDocument) operationDocument {
	clone := doc
	if doc.Result != nil {
		result := *doc.Result
		result.Findings = append([]findingDTO(nil), doc.Result.Findings...)
		if doc.Result.Error != nil {
			err := *doc.Result.Error
			result.Error = &err
		}
		clone.Result = &result
	}
	return clone
}

func terminalOperationState(state string) bool {
	switch state {
	case "succeeded", "failed", "cancelled", "interrupted", "cleanup_uncertain":
		return true
	default:
		return false
	}
}

func canonicalCancelReason(reason string) string {
	switch reason {
	case "server_shutdown", "timeout", "recovery":
		return reason
	default:
		return "user_request"
	}
}

func safeWebText(value string) string {
	return safeProjectedText(value, 4096)
}

func safeProjectedText(value string, limit int) string {
	value = strings.TrimSpace(value)
	lower := strings.ToLower(value)
	for _, marker := range []string{"token=", "secret=", "authorization:", "cookie:"} {
		if index := strings.Index(lower, marker); index >= 0 {
			value = value[:index] + "[redacted]"
			lower = strings.ToLower(value)
		}
	}
	if strings.Contains(value, "/home/") || strings.Contains(value, `C:\\Users\\`) {
		value = "[redacted path]"
	}
	return safeBoundedText(value, limit)
}

func safeBoundedText(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	return value[:limit] + "…"
}

func parseEventID(value string) (uint64, error) {
	if strings.TrimSpace(value) == "" {
		return 0, nil
	}
	id, err := strconv.ParseUint(value, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("invalid Last-Event-ID")
	}
	return id, nil
}

